ALTER TRIGGER "APP"."TG_SEQ_FPG" DISABLE;
ALTER TRIGGER "APP"."TG_SEQ_ATD" DISABLE;
ALTER TRIGGER "APP"."TG_SEQ_CXD" DISABLE;

