ALTER TRIGGER "APP"."TG_SEQ_FPG" ENABLE;
ALTER TRIGGER "APP"."TG_SEQ_ATD" ENABLE;
ALTER TRIGGER "APP"."TG_SEQ_CXD" ENABLE;

